-- 杭州 POI 知识库与城市消费系数（幂等：重复执行不会产生重复数据）
INSERT IGNORE INTO city_consumption (city, level, meal_price, transport_price, hotel_price)
VALUES ('杭州', 'high', 85.00, 45.00, 420.00);

INSERT INTO poi_knowledge (city, name, category, address, latitude, longitude,
