  UNION ALL SELECT '杭州','知味观味庄','food','杨公堤10-12号',30.255562,120.149921,85.00,90,'10:00-21:00','美食',4.6,'知味停车百年字号湖景环境，适合美食体验。'
  UNION ALL SELECT '杭州','奎元馆','food','解放路154号',30.251036,120.169842,40.00,60,'07:00-19:30','美食',4.4,'百年面馆虾爆鳝面宁式大面，适合美食体验。'
